from ta_emss.utilities.trs.commands.emssim import EmssimCommand
import re


class Rtpm_status(EmssimCommand):
    def __init__(self, method="rtpm_status", timeout=60, rpc_connection_name='localRPC'):
        super(Rtpm_status, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Rtpm_status, self).on_new_data(**data)
        if "msg" in data:
            self._ret['collected_files'] = int(re.findall(r'\d+', data['msg'])[0])
        elif ("result" in data):
            self._ret["result"] = data["result"]
